WITH rollup_totals AS (SELECT p.country, s.status, COUNT(*) AS cnt, AVG(s.balance) AS avg_balance, GROUPING_ID() AS level_id FROM accounts s JOIN customers p ON s.customer_id = p.id GROUP BY GROUPING SETS ((p.country, s.status), (p.country), ())) SELECT status, CASE WHEN status RLIKE '^(FROZEN|CLOSED)$' THEN 'EXTENDED' WHEN status RLIKE '^(OPEN)$' THEN 'PRIORITY' ELSE 'CORE' END AS status_zone FROM rollup_totals;
